    private static double log(BigDecimal value){return value.signum()==0?Double.NEGATIVE_INFINITY:Math.log(value.unscaledValue().doubleValue())-value.scale()*Math.log(10);}
    private static String value(String[] row,Map<String,Integer> columns,String name){return row[columns.get(name)];}
    private static Map<String,Map<Integer,Double>> ratios(Path file)throws Exception {var result=new HashMap<String,Map<Integer,Double>>();try(var reader=Files.newBufferedReader(file,StandardCharsets.UTF_8)){for(String line;(line=SaigeGrmInputs.line(reader,16384))!=null;){String[] f=line.strip().split("\\s+");if(f.length!=3)throw new IOException("Invalid reused variance-ratio row");double value=Double.parseDouble(f[0]);int bin=Integer.parseInt(f[2]);if(!Double.isFinite(value)||value<=0||bin<1||result.computeIfAbsent(f[1],k->new HashMap<>()).put(bin,value)!=null)throw new IOException("Invalid/duplicate reused variance ratio");}}return result;}
    private static double ratio(Map<String,Map<Integer,Double>> ratios,String kind,int bin)throws IOException {Double value=ratios.getOrDefault(kind,Map.of()).get(bin);if(value==null)throw new IOException("Missing requested variance-ratio kind/bin: "+kind+":"+bin);return value;}
    static Firth firth(Path stdout)throws Exception {if(!Files.isRegularFile(stdout)||Files.size(stdout)>64L*1048576)throw new IOException("Missing/oversized original association stdout;increase variants_per_chunk if needed");Pattern pattern=Pattern.compile("Firth approx was applied to ([0-9]+) markers\\. ([0-9]+) sucessfully converged\\.");long applied=0,converged=0,pcgFailures=0;int chunks=0;try(var reader=Files.newBufferedReader(stdout,StandardCharsets.UTF_8)){for(String line;(line=SaigeGrmInputs.line(reader,65536))!=null;){if(line.strip().equals("PCG in getPCG1ofSigmaAndGtilde did not converge. You may increase maxiter number."))pcgFailures=Math.addExact(pcgFailures,1);var match=pattern.matcher(line.strip());if(match.matches()){applied=Math.addExact(applied,Long.parseLong(match.group(1)));converged=Math.addExact(converged,Long.parseLong(match.group(2)));chunks++;}}}return new Firth(applied,converged,chunks,pcgFailures);}
